export type Market = {
  sym: string; name: string; quote: string; price: number; chg: number; vol: number
  color: string; trend: number[]
}

function rng(seed: number) {
  let s = seed >>> 0
  return () => ((s = (s * 1664525 + 1013904223) >>> 0) / 4294967296)
}

export function series(seed: number, n: number, up: number): number[] {
  const r = rng(seed)
  let v = 100
  const out: number[] = []
  for (let i = 0; i < n; i++) { v += (r() - 0.5 + up) * 4; out.push(v) }
  return out
}

export type Candle = { t?: number; o: number; h: number; l: number; c: number; v: number }
export function candles(seed: number, n: number, base: number): Candle[] {
  const r = rng(seed)
  let p = base * 0.985
  const out: Candle[] = []
  for (let i = 0; i < n; i++) {
    const o = p
    const c = o + (r() - 0.46) * base * 0.0035
    const h = Math.max(o, c) + r() * base * 0.0015
    const l = Math.min(o, c) - r() * base * 0.0015
    out.push({ o, h, l, c, v: 0.3 + r() })
    p = c
  }
  const k = base / out[out.length - 1].c
  return out.map(x => ({ o: x.o * k, h: x.h * k, l: x.l * k, c: x.c * k, v: x.v }))
}

