export function compact(n: number, num: (n: number, d?: number) => string): string {
  if (n >= 1e9) return num(n / 1e9) + 'B'
  if (n >= 1e6) return num(n / 1e6) + 'M'
  return num(n)
}

export function priceDigits(p: number) { return p >= 1000 ? 2 : p >= 1 ? 2 : 4 }
